import re,pandas as pd,numpy as np
els=['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
df=pd.read_csv('/work/b3_supercon_target.csv')
def parse(s):
 d={}
 for e,n in re.findall(r'([A-Z][a-z]?)([0-9]*(?:\.[0-9]+)?)',s): d[e]=d.get(e,0)+float(n or 1)
 z=sum(d.values()); return {k:v/z for k,v in d.items()}
X=pd.DataFrame([{e:parse(s).get(e,0) for e in els} for s in df.composition])
print(pd.DataFrame({'calc':X.max(),'given':[.697674,.454545,.333333,.285714,.4,.272727,.78,.521978,.502513,.98,.972,.265043,.5,1,.5,.28,1,.9918,1,.6]},index=els))
print(pd.concat([df,X],axis=1).tail(35).to_string(index=False))

